-- as 21 de geografia voltam com o id original; node e order_index
-- vem da linha que o seed criou no lugar delas.
insert into questions (id, catalog_node_id, prompt, options, correct_index, explanation, order_index, difficulty) values
  ('03c5ef46-9631-41d1-9d66-b8bf7be5f8e2', '6d679874-fdd0-4b6d-a3b8-76488172e735', 'O Rio Meia Ponte é afluente de qual rio maior?',
   array['Rio Araguaia', 'Rio São Francisco', 'Rio Tocantins', 'Rio Paranaíba'], 3,
   'O Meia Ponte deságua no Paranaíba, integrando a bacia do Paraná.', 3, 'medio'),
  ('08646ded-ae73-49ee-a05e-53ae2109ec91', '5a03b58b-9347-425a-a4c8-b8117a351d37', 'Ao se encontrar com o Rio Grande, o Rio Paranaíba dá origem a qual rio?',
   array['Rio Tocantins', 'Rio Paraguai', 'Rio Araguaia', 'Rio Paraná'], 3,
   'A junção do Paranaíba com o Rio Grande forma o Rio Paraná.', 3, 'dificil'),
  ('10c33054-4ee9-46bc-a76d-6454063f1dbb', 'c1b714b7-f1e5-45ab-a154-0d610e35f4d4', 'No Rio Corumbá localiza-se um importante aproveitamento energético. Qual?',
   array['O Porto de Corumbá', 'A Represa do Castanhão', 'A Usina Hidrelétrica de Corumbá', 'A Usina Nuclear de Corumbá'], 2,
   'O Corumbá abriga usinas hidrelétricas, com destaque para a UHE Corumbá.', 2, 'medio'),
  ('4a558e00-c458-48ae-aec8-412b0563aa99', 'b70eaa36-0f04-4dc3-9a1d-136986b0c125', 'Diferentemente do Meia Ponte (bacia do Paraná), o Rio das Almas corre para qual bacia?',
   array['Bacia Tocantins-Araguaia', 'Bacia do Uruguai', 'Bacia do Paraná', 'Bacia do São Francisco'], 0,
   'O Rio das Almas pertence à bacia Tocantins-Araguaia; junto ao Rio Maranhão ajuda a formar o Rio Tocantins.', 1, 'dificil'),
  ('52c6d456-906c-4f15-ae4f-76d610566afa', 'f433d7c9-1e81-4194-b72f-72353b47da82', 'O Rio Vermelho pertence à mesma bacia de qual grande rio goiano, do qual é afluente?',
   array['Rio Paraná', 'Rio São Francisco', 'Rio Paranaíba', 'Rio Araguaia'], 3,
   'O Rio Vermelho é afluente do Araguaia, integrando a bacia Tocantins-Araguaia.', 3, 'medio'),
  ('58895b64-dbfc-49e9-a5a6-e84b954cc959', '0d84ad26-a469-4c2b-b022-f0c5bb724e13', 'O Rio Vermelho, que passa pela Cidade de Goiás, deságua em qual rio?',
   array['No Rio São Francisco', 'No Rio Paraná', 'No Rio Araguaia', 'No Rio Meia Ponte'], 2,
   'O Rio Vermelho é afluente do Araguaia, dentro da bacia Tocantins-Araguaia.', 4, 'medio'),
  ('5f94146c-93d8-4971-8cf7-e5cb8d8c003d', 'c1b714b7-f1e5-45ab-a154-0d610e35f4d4', 'A região banhada pelo Rio Corumbá fica próxima a qual destino goiano conhecido por suas águas termais?',
   array['Pirenópolis', 'Chapada dos Veadeiros', 'Caldas Novas', 'Cidade de Goiás'], 2,
   'A região do Corumbá, no sul goiano, está próxima de Caldas Novas, famosa pelas águas termais.', 3, 'dificil'),
  ('694f3756-7c2b-4948-8fda-061eea2ea71c', '0d84ad26-a469-4c2b-b022-f0c5bb724e13', 'No período de seca, o Araguaia é famoso por um fenômeno que atrai turismo, sobretudo na cidade goiana de Aruanã. Que fenômeno é esse?',
   array['O congelamento das margens', 'A inversão do sentido da correnteza', 'O desaparecimento total do leito', 'A formação de extensas praias fluviais de areia branca'], 3,
   'Na estiagem, o nível baixa e surgem grandes praias de areia, como as de Aruanã.', 3, 'medio'),
  ('6abca4fc-3f41-4d28-b12c-f0dac73ac56d', '5a03b58b-9347-425a-a4c8-b8117a351d37', 'O curso do Rio Paranaíba se destaca economicamente, sobretudo, pela presença de:',
   array['Grandes usinas hidrelétricas, como Itumbiara e São Simão', 'Minas de carvão mineral no leito', 'Portos de navios oceânicos', 'Geleiras usadas para turismo'], 0,
   'O Paranaíba é muito aproveitado para geração de energia, com usinas como Itumbiara, Cachoeira Dourada e São Simão.', 4, 'medio'),
  ('7df9a7b9-4224-4397-aca0-5dd7e338583a', '5a03b58b-9347-425a-a4c8-b8117a351d37', 'O Rio Paranaíba pertence a qual bacia hidrográfica?',
   array['Bacia do São Francisco', 'Bacia Amazônica', 'Bacia Tocantins-Araguaia', 'Bacia do Paraná'], 3,
   'O Paranaíba integra a bacia do Paraná (bacia do Prata).', 2, 'medio'),
  ('8289c185-a540-4624-b80b-99707bac89f4', 'b70eaa36-0f04-4dc3-9a1d-136986b0c125', 'O Rio das Almas banha o norte goiano, passando por regiões de municípios como:',
   array['Catalão e Ipameri', 'Goianésia, Barro Alto e Niquelândia', 'Rio Verde e Jataí', 'Aparecida de Goiânia e Trindade'], 1,
   'O das Almas percorre o norte do estado, próximo a Goianésia, Barro Alto e Niquelândia.', 2, 'medio'),
  ('8395b9ee-1b57-41b8-b88c-76233b822cc3', '0d84ad26-a469-4c2b-b022-f0c5bb724e13', 'O Rio Araguaia forma trechos da divisa natural de Goiás com quais estados?',
   array['Mato Grosso do Sul e São Paulo', 'Pará e Maranhão', 'Bahia e Minas Gerais', 'Mato Grosso e Tocantins'], 3,
   'O Araguaia separa Goiás de Mato Grosso (a oeste) e do Tocantins (ao norte).', 1, 'facil'),
  ('9dbdd106-bddc-4544-837f-a06f361d1338', '6d679874-fdd0-4b6d-a3b8-76488172e735', 'Além da importância ambiental, o Rio Meia Ponte é estratégico para a Região Metropolitana de Goiânia porque:',
   array['Serve de fronteira internacional', 'Participa do abastecimento de água da região', 'É uma rota de navios de carga', 'Abriga a maior geleira do Brasil'], 1,
   'O Meia Ponte é uma das fontes de água para o abastecimento da região metropolitana.', 4, 'medio'),
  ('ceb61090-afd5-4cbc-a102-4f9e1974d1ce', 'b70eaa36-0f04-4dc3-9a1d-136986b0c125', 'O nome do Rio das Almas aparece ligado à história de povoamento do:',
   array['Pantanal goiano', 'Sertão nordestino', 'Norte/centro de Goiás, região de mineração antiga', 'Litoral goiano'], 2,
   'O das Almas corta o centro-norte goiano, área ligada à antiga mineração e ao povoamento colonial.', 3, 'medio'),
  ('d81ba35d-55e1-4b06-a992-03077e6133a3', 'f433d7c9-1e81-4194-b72f-72353b47da82', 'O Rio Vermelho banha qual cidade histórica goiana, antiga capital do estado?',
   array['Cidade de Goiás (Goiás Velho)', 'Cristalina', 'Pirenópolis', 'Corumbá de Goiás'], 0,
   'O Rio Vermelho atravessa a Cidade de Goiás, primeira capital do estado e patrimônio histórico.', 1, 'facil'),
  ('e43982b1-ec6b-471c-8365-704f015b4048', '0d84ad26-a469-4c2b-b022-f0c5bb724e13', 'A qual grande bacia hidrográfica pertence o Rio Araguaia?',
   array['Bacia do Paraná', 'Bacia Amazônica', 'Bacia Tocantins-Araguaia', 'Bacia do São Francisco'], 2,
   'O Araguaia é um dos principais rios da bacia Tocantins-Araguaia.', 2, 'medio'),
  ('e441bb2c-1622-47e4-a0e2-14616632dbb9', '6d679874-fdd0-4b6d-a3b8-76488172e735', 'Qual é um dos principais problemas ambientais associados ao Rio Meia Ponte?',
   array['Excesso de gelo nas margens', 'Ausência completa de vida aquática desde a nascente', 'Elevado grau de poluição por esgoto e ocupação urbana', 'Salinização por água do mar'], 2,
   'Por atravessar a área metropolitana de Goiânia, o Meia Ponte sofre com lançamento de esgoto e degradação.', 2, 'medio'),
  ('e8bf08d3-ae1c-4628-bed2-995ffdcd64d1', 'c1b714b7-f1e5-45ab-a154-0d610e35f4d4', 'O Rio Corumbá é afluente de qual rio, integrando a bacia do Paraná?',
   array['Rio Paranaíba', 'Rio São Francisco', 'Rio Tocantins', 'Rio Araguaia'], 0,
   'O Corumbá deságua no Paranaíba, dentro da bacia do Paraná.', 1, 'facil'),
  ('d2224715-16d1-4064-9820-127f38948070', '6d679874-fdd0-4b6d-a3b8-76488172e735', 'O Rio Meia Ponte e o principal rio que corta qual cidade goiana?',
   array['Goiânia', 'Anápolis', 'Catalão', 'Rio Verde'], 0,
   'O Meia Ponte atravessa a região de Goiânia, capital do estado.', 1, 'facil'),
  ('e5a46308-c72a-4f6f-8f6a-5fece7c2ddd5', '5a03b58b-9347-425a-a4c8-b8117a351d37', 'O Rio Paranaíba forma a divisa de Goiás principalmente com quais estados?',
   array['Tocantins e Bahia', 'Minas Gerais e Mato Grosso do Sul', 'São Paulo e Paraná', 'Mato Grosso e Para'], 1,
   'O Paranaíba separa Goiás de Minas Gerais (a leste/sul) e do Mato Grosso do Sul (a sudoeste).', 1, 'facil'),
  ('148d6230-1ae9-4662-ac3c-d586fdc95daf', 'f433d7c9-1e81-4194-b72f-72353b47da82', 'Em 2001, o Rio Vermelho ficou marcado por qual evento na Cidade de Goiás?',
   array['A descoberta de petróleo', 'Uma seca que secou totalmente o leito', 'A construção de uma usina nuclear', 'Uma grande enchente que atingiu o centro histórico'], 3,
   'A enchente de 2001 invadiu o centro histórico da Cidade de Goiás, causando grandes danos ao patrimônio.', 2, 'dificil')
on conflict (id) do nothing;

insert into question_translations (question_id, locale, prompt, options, explanation) values
  ('03c5ef46-9631-41d1-9d66-b8bf7be5f8e2', 'en', 'The Meia Ponte River is a tributary of which larger river?',
   array['Araguaia River', 'São Francisco River', 'Tocantins River', 'Paranaíba River'],
   'The Meia Ponte flows into the Paranaíba, as part of the Paraná basin.'),
  ('03c5ef46-9631-41d1-9d66-b8bf7be5f8e2', 'es', 'El río Meia Ponte es afluente de ¿qué río mayor?',
   array['Río Araguaia', 'Río São Francisco', 'Río Tocantins', 'Río Paranaíba'],
   'El Meia Ponte desemboca en el Paranaíba y forma parte de la cuenca del Paraná.'),
  ('08646ded-ae73-49ee-a05e-53ae2109ec91', 'en', 'When it meets the Grande River, the Paranaíba River gives rise to which river?',
   array['Tocantins River', 'Paraguay River', 'Araguaia River', 'Paraná River'],
   'The junction of the Paranaíba and the Grande forms the Paraná River.'),
  ('08646ded-ae73-49ee-a05e-53ae2109ec91', 'es', 'Al encontrarse con el río Grande, el río Paranaíba da origen a ¿qué río?',
   array['Río Tocantins', 'Río Paraguay', 'Río Araguaia', 'Río Paraná'],
   'La unión del Paranaíba con el río Grande forma el río Paraná.'),
  ('10c33054-4ee9-46bc-a76d-6454063f1dbb', 'en', 'An important energy project is located on the Corumbá River. Which one?',
   array['The Port of Corumbá', 'The Castanhão Reservoir', 'The Corumbá Hydroelectric Plant', 'The Corumbá Nuclear Plant'],
   'The Corumbá has hydroelectric plants, most notably the Corumbá HPP.'),
  ('10c33054-4ee9-46bc-a76d-6454063f1dbb', 'es', 'En el río Corumbá se ubica un importante aprovechamiento energético. ¿Cuál?',
   array['El Puerto de Corumbá', 'El Embalse de Castanhão', 'La Central Hidroeléctrica de Corumbá', 'La Central Nuclear de Corumbá'],
   'El Corumbá alberga centrales hidroeléctricas, en especial la UHE Corumbá.'),
  ('4a558e00-c458-48ae-aec8-412b0563aa99', 'en', 'Unlike the Meia Ponte (Paraná basin), the Das Almas River flows toward which basin?',
   array['Tocantins-Araguaia Basin', 'Uruguay Basin', 'Paraná Basin', 'São Francisco Basin'],
   'The Das Almas River belongs to the Tocantins-Araguaia basin; together with the Maranhão River it helps form the Tocantins River.'),
  ('4a558e00-c458-48ae-aec8-412b0563aa99', 'es', 'A diferencia del Meia Ponte (cuenca del Paraná), ¿hacia qué cuenca corre el río das Almas?',
   array['Cuenca Tocantins-Araguaia', 'Cuenca del Uruguay', 'Cuenca del Paraná', 'Cuenca del São Francisco'],
   'El río das Almas pertenece a la cuenca Tocantins-Araguaia; junto con el río Maranhão ayuda a formar el río Tocantins.'),
  ('52c6d456-906c-4f15-ae4f-76d610566afa', 'en', 'The Vermelho River belongs to the same basin as which major river of Goiás, of which it is a tributary?',
   array['Paraná River', 'São Francisco River', 'Paranaíba River', 'Araguaia River'],
   'The Vermelho River is a tributary of the Araguaia, within the Tocantins-Araguaia basin.'),
  ('52c6d456-906c-4f15-ae4f-76d610566afa', 'es', 'El río Vermelho pertenece a la misma cuenca de ¿qué gran río de Goiás, del cual es afluente?',
   array['Río Paraná', 'Río São Francisco', 'Río Paranaíba', 'Río Araguaia'],
   'El río Vermelho es afluente del Araguaia y forma parte de la cuenca Tocantins-Araguaia.'),
  ('58895b64-dbfc-49e9-a5a6-e84b954cc959', 'en', 'The Vermelho River, which flows through Cidade de Goiás, empties into which river?',
   array['Into the São Francisco River', 'Into the Paraná River', 'Into the Araguaia River', 'Into the Meia Ponte River'],
   'The Vermelho River is a tributary of the Araguaia, within the Tocantins-Araguaia basin.'),
  ('58895b64-dbfc-49e9-a5a6-e84b954cc959', 'es', 'El río Vermelho, que pasa por la Cidade de Goiás, desemboca en ¿qué río?',
   array['En el río São Francisco', 'En el río Paraná', 'En el río Araguaia', 'En el río Meia Ponte'],
   'El río Vermelho es afluente del Araguaia, dentro de la cuenca Tocantins-Araguaia.'),
  ('5f94146c-93d8-4971-8cf7-e5cb8d8c003d', 'en', 'The region along the Corumbá River is close to which Goiás destination known for its hot springs?',
   array['Pirenópolis', 'Chapada dos Veadeiros', 'Caldas Novas', 'Cidade de Goiás'],
   'The Corumbá region, in southern Goiás, is close to Caldas Novas, famous for its hot springs.'),
  ('5f94146c-93d8-4971-8cf7-e5cb8d8c003d', 'es', 'La región bañada por el río Corumbá está cerca de ¿qué destino de Goiás conocido por sus aguas termales?',
   array['Pirenópolis', 'Chapada dos Veadeiros', 'Caldas Novas', 'Cidade de Goiás'],
   'La región del Corumbá, en el sur de Goiás, está cerca de Caldas Novas, famosa por sus aguas termales.'),
  ('694f3756-7c2b-4948-8fda-061eea2ea71c', 'en', 'In the dry season, the Araguaia is famous for a phenomenon that attracts tourists, especially in the town of Aruanã, in Goiás. What is it?',
   array['The freezing of its banks', 'The reversal of the current', 'The complete disappearance of the riverbed', 'The formation of long white-sand river beaches'],
   'During the dry season, the water level drops and large sand beaches appear, such as those in Aruanã.'),
  ('694f3756-7c2b-4948-8fda-061eea2ea71c', 'es', 'En la época seca, el Araguaia es famoso por un fenómeno que atrae turismo, sobre todo en la ciudad de Aruanã, en Goiás. ¿Qué fenómeno es?',
   array['El congelamiento de las orillas', 'La inversión del sentido de la corriente', 'La desaparición total del cauce', 'La formación de extensas playas fluviales de arena blanca'],
   'En el estiaje, el nivel baja y surgen grandes playas de arena, como las de Aruanã.'),
  ('6abca4fc-3f41-4d28-b12c-f0dac73ac56d', 'en', 'The course of the Paranaíba River stands out economically mainly for the presence of:',
   array['Large hydroelectric plants, such as Itumbiara and São Simão', 'Coal mines in the riverbed', 'Ports for ocean-going ships', 'Glaciers used for tourism'],
   'The Paranaíba is widely used for power generation, with plants such as Itumbiara, Cachoeira Dourada and São Simão.'),
  ('6abca4fc-3f41-4d28-b12c-f0dac73ac56d', 'es', 'El curso del río Paranaíba se destaca económicamente, sobre todo, por la presencia de:',
   array['Grandes centrales hidroeléctricas, como Itumbiara y São Simão', 'Minas de carbón en el cauce', 'Puertos de barcos oceánicos', 'Glaciares usados para turismo'],
   'El Paranaíba se aprovecha mucho para generar energía, con centrales como Itumbiara, Cachoeira Dourada y São Simão.'),
  ('7df9a7b9-4224-4397-aca0-5dd7e338583a', 'en', 'Which river basin does the Paranaíba River belong to?',
   array['São Francisco Basin', 'Amazon Basin', 'Tocantins-Araguaia Basin', 'Paraná Basin'],
   'The Paranaíba is part of the Paraná basin (the Río de la Plata basin).'),
  ('7df9a7b9-4224-4397-aca0-5dd7e338583a', 'es', '¿A qué cuenca hidrográfica pertenece el río Paranaíba?',
   array['Cuenca del São Francisco', 'Cuenca Amazónica', 'Cuenca Tocantins-Araguaia', 'Cuenca del Paraná'],
   'El Paranaíba forma parte de la cuenca del Paraná (cuenca del Plata).'),
  ('8289c185-a540-4624-b80b-99707bac89f4', 'en', 'The Das Almas River flows through northern Goiás, passing through the areas of municipalities such as:',
   array['Catalão and Ipameri', 'Goianésia, Barro Alto and Niquelândia', 'Rio Verde and Jataí', 'Aparecida de Goiânia and Trindade'],
   'The Das Almas runs through the north of the state, near Goianésia, Barro Alto and Niquelândia.'),
  ('8289c185-a540-4624-b80b-99707bac89f4', 'es', 'El río das Almas baña el norte de Goiás y pasa por regiones de municipios como:',
   array['Catalão e Ipameri', 'Goianésia, Barro Alto y Niquelândia', 'Rio Verde y Jataí', 'Aparecida de Goiânia y Trindade'],
   'El das Almas recorre el norte del estado, cerca de Goianésia, Barro Alto y Niquelândia.'),
  ('8395b9ee-1b57-41b8-b88c-76233b822cc3', 'en', 'The Araguaia River forms stretches of the natural border between Goiás and which states?',
   array['Mato Grosso do Sul and São Paulo', 'Pará and Maranhão', 'Bahia and Minas Gerais', 'Mato Grosso and Tocantins'],
   'The Araguaia separates Goiás from Mato Grosso (to the west) and from Tocantins (to the north).'),
  ('8395b9ee-1b57-41b8-b88c-76233b822cc3', 'es', 'El río Araguaia forma tramos de la frontera natural de Goiás con ¿qué estados?',
   array['Mato Grosso do Sul y São Paulo', 'Pará y Maranhão', 'Bahía y Minas Gerais', 'Mato Grosso y Tocantins'],
